#!/usr/bin/env bash
# gen-shims.sh — (re)generate the bin/<tool>-<variant> shim scripts from
# builds/registry.tsv. Shims let you call every build from anywhere via a
# unique name, e.g.:  ffmpeg-asan-ubsan -i poc.mp4 -f null -
#
# Usage: scripts/gen-shims.sh
set -euo pipefail

FFENV_LIB_DIR="$(cd -P "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FFENV_ROOT="$(dirname "$FFENV_LIB_DIR")"
# shellcheck source=ffenv-lib.sh
. "$FFENV_LIB_DIR/ffenv-lib.sh"

read -r -d '' SHIM_TEMPLATE <<'TPL' || true
#!/usr/bin/env bash
# ffmpeg-env shim: __TOOL__ @ variant __VARIANT__
# Auto-generated by scripts/gen-shims.sh — regenerate instead of editing.
set -euo pipefail

_ffenv_self="${BASH_SOURCE[0]}"
while [ -L "$_ffenv_self" ]; do
  _ffenv_dir="$(cd -P "$(dirname "$_ffenv_self")" && pwd)"
  _ffenv_self="$(readlink "$_ffenv_self")"
  case "$_ffenv_self" in
    /*) ;;
    *) _ffenv_self="$_ffenv_dir/$_ffenv_self" ;;
  esac
done
FFENV_ROOT="$(cd -P "$(dirname "$_ffenv_self")/.." && pwd)"
FFENV_VARIANT="__VARIANT__"
FFENV_TOOL="__TOOL__"

_ffenv_bin="$FFENV_ROOT/builds/$FFENV_VARIANT/bin/$FFENV_TOOL"
if [ ! -x "$_ffenv_bin" ]; then
  if [ "${FFENV_AUTO_FETCH:-1}" = "1" ] && [ -x "$FFENV_ROOT/scripts/fetch-builds.sh" ]; then
    echo "ffenv: '$FFENV_TOOL' for variant '$FFENV_VARIANT' not installed; fetching build..." >&2
    "$FFENV_ROOT/scripts/fetch-builds.sh" "$FFENV_VARIANT" >&2 || true
  fi
fi
if [ ! -x "$_ffenv_bin" ]; then
  echo "ffenv: missing $_ffenv_bin" >&2
  echo "ffenv: install with: $FFENV_ROOT/scripts/fetch-builds.sh $FFENV_VARIANT" >&2
  exit 127
fi

_ffenv_lib="$FFENV_ROOT/builds/$FFENV_VARIANT/lib"
if [ -d "$_ffenv_lib" ]; then
  case ":${LD_LIBRARY_PATH:-}:" in
    *":$_ffenv_lib:"*) ;;
    *) export LD_LIBRARY_PATH="$_ffenv_lib${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}" ;;
  esac
fi
export ASAN_OPTIONS="${ASAN_OPTIONS:-detect_leaks=0:abort_on_error=1:halt_on_error=1:symbolize=1:allocator_may_return_null=1}"
export UBSAN_OPTIONS="${UBSAN_OPTIONS:-print_stacktrace=1:halt_on_error=1}"

exec "$_ffenv_bin" "$@"
TPL

mkdir -p "$FFENV_ROOT/bin"
count=0
while IFS=$'\t' read -r name tools _u _s _b _a _l _d; do
  IFS=',' read -ra tool_list <<< "$tools"
  for tool in "${tool_list[@]}"; do
    [ -n "$tool" ] || continue
    shim="$FFENV_ROOT/bin/$tool-$name"
    printf '%s\n' "${SHIM_TEMPLATE//__VARIANT__/$name}" | sed "s/__TOOL__/$tool/g" > "$shim"
    chmod +x "$shim"
    count=$((count + 1))
    echo "  shim: $(basename "$shim")"
  done
done < <(ffenv_registry_rows)

echo "generated $count shims in $FFENV_ROOT/bin/"
